# Exact: quaternion algebra over F = Q(w), w = m + 1/m (2w^2 - w - 2 = 0, i.e. F = Q(sqrt17)),
# generated by the SL_2-normalized images g = rho(ba)/m and h = rho(abxyxy)/(4m(m+1)^2)
# of the two generators of the derived subgroup D (Titz Mite-Witzel p.10-11).
from fractions import Fraction as Fr
exec(open("radu-pgl2-core.py").read())

inv_m = norm({(3, 0): Fr(-1), (2, 0): Fr(1, 2), (1, 0): Fr(-1), (0, 0): Fr(1, 2)})
# 1/(m+1) = -q/8, q = 2m^3 - 3m^2 + 5m - 6
inv_m1 = norm({(3, 0): Fr(-2, 8), (2, 0): Fr(3, 8), (1, 0): Fr(-5, 8), (0, 0): Fr(6, 8)})
assert mul(inv_m, M_) == const(1), mul(inv_m, M_)
assert mul(inv_m1, add(M_, const(1))) == const(1)

def smul(c, A):
    return [[mul(c, A[i][j]) for j in range(2)] for i in range(2)]

def tr(A):
    return add(A[0][0], A[1][1])

def in_F(v):
    # v in span{1, w} with w = 1/2 + m^2/2 - m^3 ; returns (alpha, beta) or None
    if any(k[1] != 0 for k in v):
        return None
    c = [v.get((i, 0), Fr(0)) for i in range(4)]
    if c[1] != 0 or c[2] != -c[3] / 2:
        return None
    beta = -c[3]
    alpha = c[0] - beta / 2
    return (alpha, beta)

g = smul(inv_m, prod(b, a))
k = mul(const(4), mul(M_, mul(add(M_, const(1)), add(M_, const(1)))))
invk = mul(Fr(1, 4) and const(Fr(1, 4)), mul(inv_m, mul(inv_m1, inv_m1)))
h = smul(invk, prod(a, b, x, y, x, y))
for name, A in (("g", g), ("h", h)):
    d = add(mul(A[0][0], A[1][1]), neg(mul(A[0][1], A[1][0])))
    print("det", name, "=", in_F(d))
gh = mmul(g, h)
tg, th, tgh = in_F(tr(g)), in_F(tr(h)), in_F(tr(gh))
print("tr g =", tg, " tr h =", th, " tr gh =", tgh, " (pairs alpha + beta*w)")

def Fmul(p, q):  # (a + b w)(c + d w), w^2 = (w + 2)/2
    a1, b1 = p; a2, b2 = q
    return (a1 * a2 + b1 * b2 * 1, a1 * b2 + b1 * a2 + b1 * b2 * Fr(1, 2))
def Fadd(p, q):
    return (p[0] + q[0], p[1] + q[1])
def Fneg(p):
    return (-p[0], -p[1])
def Fnorm(p):  # w1 + w2 = 1/2, w1 w2 = -1
    a1, b1 = p
    return a1 * a1 + a1 * b1 * Fr(1, 2) - b1 * b1
def Fnum(p, wv):
    return float(p[0]) + float(p[1]) * wv

trcomm = Fadd(Fadd(Fadd(Fmul(tg, tg), Fmul(th, th)), Fmul(tgh, tgh)), Fneg(Fadd(Fmul(Fmul(tg, th), tgh), (Fr(2), Fr(0)))))
e1 = Fadd(Fmul(tg, tg), (Fr(-4), Fr(0)))
e2 = Fadd(trcomm, (Fr(-2), Fr(0)))
print("Hilbert symbol entries: tr^2 g - 4 =", e1, " tr[g,h] - 2 =", e2)
print("norms to Q:", Fnorm(e1), Fnorm(e2))
import math
for wv in ((1 + math.sqrt(17)) / 4, (1 - math.sqrt(17)) / 4):
    print("real place w=%.6f: tr^2g-4 = %.6f, tr[g,h]-2 = %.6f" % (wv, Fnum(e1, wv), Fnum(e2, wv)))
basis = [ [[const(1), {}], [{}, const(1)]], g, h, gh ]
T = [[in_F(tr(mmul(basis[i], basis[j]))) for j in range(4)] for i in range(4)]
print("trace form entries in F:", all(t is not None for row in T for t in row))
# determinant over F by cofactor expansion
def Fdet(Mx):
    n = len(Mx)
    if n == 1:
        return Mx[0][0]
    tot = (Fr(0), Fr(0))
    for j in range(n):
        minor = [row[:j] + row[j + 1:] for row in Mx[1:]]
        term = Fmul(Mx[0][j], Fdet(minor))
        tot = Fadd(tot, term if j % 2 == 0 else Fneg(term))
    return tot
dT = Fdet(T)
print("Gram determinant det tr(e_i e_j) =", dT, " norm to Q =", Fnorm(dT))
print("DONE")
